import type { PagesFunction } from '@cloudflare/workers-types'
import type { DeliveryEnv } from '../_lib/env'
import { applySecurityHeaders, CLIENT_PAGE_CSP } from '../_lib/security-headers'

// Pages `_headers` is not applied to Function responses. The /p client-delivery
// pages (valid link, dead link, 405) are generated by Functions, so their
// security headers — including the same CSP the public site uses — are applied
// here. Media responses for this prefix are served by /p/<token>/preview and
// /download and already set nosniff + no-store; the CSP is only attached to the
// HTML documents.
export const onRequest: PagesFunction<DeliveryEnv, never, Record<string, unknown>> = async (
  context,
) => {
  const response = await context.next()
  return applySecurityHeaders(response, { csp: CLIENT_PAGE_CSP })
}
